uint16_t img_data_get_number(void)
{
    return ARRAY_SIZE(img_list);
}

uint8_t  img_data_has_clut(int fmt)
{
    if (GPU_IMG_FMT_LX(fmt) || \
        GPU_IMG_FMT_AX(fmt) || \
        GPU_IMG_FMT_ALXX(fmt)) {
        return true;
    } else {
        return false;
    }
}





